  async function readUpload(file,fallback){
    if(!file?.size)return fallback;
    if(file.size>8_000_000||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('ارفعي صورة JPG أو PNG أو WebP أصغر من 8 ميجابايت.');
    const url=URL.createObjectURL(file),img=new Image();
    try{
      await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('تعذّرت قراءة الصورة.'));img.src=url});
      const scale=Math.min(1,1400/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);
      if(!canvas.width||!canvas.height)throw Error('الصورة غير صالحة.');
      const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(img,0,0,canvas.width,canvas.height);
      for(const quality of [.85,.7,.5]){const data=canvas.toDataURL('image/jpeg',quality);if(data.length<=700000)return data}
      throw Error('الصورة كبيرة للحفظ؛ اختاري صورة أصغر.');
    }finally{URL.revokeObjectURL(url)}
  }
  function delivery(){
    return `<div class="admin-intro"><div><h2>تسعيرة التوصيل</h2><p>حددي رسوم كل محافظة من مكان واحد.</p></div><span class="section-count-chip">${Object.keys(S.deliveryFees).length} محافظات</span></div><div class="delivery-settings-layout"><form id="deliveryFeesForm" class="panel delivery-rates-panel"><div class="panel-head"><div><h3>المحافظات ورسوم التوصيل</h3><small>التسعيرة بالشيكل وتظهر قبل تأكيد الطلب</small></div>${icon('truck')}</div><div class="delivery-rate-list">${Object.entries(S.deliveryFees).map(([region,fee],i)=>`<div class="delivery-rate-row"><span class="delivery-region-index">${String(i+1).padStart(2,'0')}</span><div class="delivery-region-copy"><label for="deliveryRate${i}">${esc(region)}</label><span class="delivery-rate-result ${fee===0?'is-free':''}">${fee===0?'توصيل مجاني':S.money(fee)}</span></div><div class="delivery-currency-input"><input id="deliveryRate${i}" name="fee_${esc(region)}" type="number" lang="en" dir="ltr" inputmode="decimal" min="0" step="0.01" value="${fee}" required aria-label="رسوم التوصيل إلى ${esc(region)}"><span>₪</span></div></div>`).join('')}</div><div class="delivery-save-bar"><small>استخدمي 0 للتوصيل المجاني.</small><button type="submit" class="button button-dark">حفظ التسعيرة</button></div><p id="deliveryFeesError" class="form-error" role="alert"></p></form><aside class="panel delivery-settings-info"><span class="settings-info-icon">${icon('truck')}</span><h3>سعر واضح قبل الطلب</h3><p>رسوم المحافظة تُضاف إلى سعر القطع في ملخص الشراء.</p><div><strong>الطلبات الجديدة</strong><p>تستخدم التسعيرة المحفوظة هنا.</p></div><div><strong>الطلبات السابقة</strong><p>تحتفظ برسومها الأصلية عند تغيير التسعيرة.</p></div><div><strong>التوصيل المجاني</strong><p>أدخلي 0 للمحافظة المطلوب إعفاؤها.</p></div></aside></div>`;
  }
  function render(){if(!S.currentAdmin()){location.replace('./admin-login.html');return}const content={overview,products,orders,customers,payments,categories,promotions,delivery,notifications,visitors};$('pageTitle').textContent=titles[view];$('adminContent').innerHTML=content[view]();document.querySelectorAll('.nav-item').forEach(x=>{x.classList.toggle('active',x.dataset.view===view);x.dataset.view===view?x.setAttribute('aria-current','page'):x.removeAttribute('aria-current')});const count=S.read().orders.filter(o=>o.status==='جديد').length;$('newOrderCount').textContent=count;$('newOrderCount').hidden=count===0;refreshNotificationUI()}
