  function syncProductPreview(){
    const form=$('productForm');if(!form)return;
    $('previewName').textContent=form.elements.name.value.trim()||'اسم المنتج';
    $('previewCategory').textContent=form.elements.category.value||'اختاري الفئة';
    const price=Number(form.elements.price.value);$('previewPrice').textContent=Number.isFinite(price)&&price>0?S.money(price):'حددي سعر البيع';
    const total=S.sizes.reduce((sum,size)=>sum+Math.max(0,Math.floor(Number(form.elements['stock_'+size].value)||0)),0);$('editorStockTotal').textContent=total+' قطعة';
  }
  function previewProductImage(){
    const form=$('productForm');if(!form)return;
    if(editorPreviewUrl){URL.revokeObjectURL(editorPreviewUrl);editorPreviewUrl=null}
    const file=form.elements.imageFile.files[0],link=form.elements.image.value.trim();
    if(file&&(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8_000_000)){form.elements.imageFile.value='';notify('ارفعي صورة JPG أو PNG أو WebP أصغر من 8 ميجابايت.');return previewProductImage()}
    const show=!!file||!!link;const img=$('productPreviewImage');img.hidden=!show;$('productImagePlaceholder').hidden=show;
    if(file){editorPreviewUrl=URL.createObjectURL(file);img.src=editorPreviewUrl}else if(link)img.src=S.image(link);
  }
